"""Write brief 118 independent review hand-ins, without changing designs."""
import json, pathlib, re
PM=next(p for p in pathlib.Path(__file__).resolve().parents if (p/'REPO-GUIDE.md').exists())/'docs/production/claude-pm'
A=json.loads((PM/'assets/brief118-source-audit.json').read_text(encoding='utf8'))
def polish(value):
    """Expand compact review notation while keeping URLs and file/code spans exact."""
    terms={'TableIV':'Table IV','TableI:':'Table I:','Book2a':'Book 2a','TableS2a.1':'Table S2a.1','NSWDoE':'NSW DoE','CancerAustralia':'Cancer Australia','ChiefScientist':'Chief Scientist','BritishDoctors':'British Doctors','BCMedicalJournal':'BC Medical Journal','OriginalBMJ':'Original BMJ','MerckP5271':'Merck P5271','Merck09158':'Merck 09158','Merck360538':'Merck 360538','Scharlab7015':'Scharlab 7015','Cr(VI)teacher':'Cr(VI) teacher','per1,000':'per 1,000','per100,000':'per 100,000','all-causemortality':'all-cause mortality','all-cause survival':'all-cause survival','current31':'current 31','full31':'full 31','exact31':'exact 31','31annualmortalityrows':'31 annual mortality rows','31rows':'31 rows','annualseries':'annual series','standardpopulations':'standard populations','standardmortality':'standard mortality','populationstandard':'population standard','standard column':'standard column','CountYears':'Count Years','asprojections':'as projections','dataartifact':'data artifact','both2001':'both 2001','columnH':'column H','age35+':'age 35+','rate208.6':'rate 208.6','rate142.7':'rate 142.7','count34216':'count 34216','count53545':'count 53545','deaths34216':'deaths 34216','deaths53545':'deaths 53545','age18+':'age 18+','age14+':'age 14+','degrees,five-day':'degrees, five-day','dark20-degree':'dark, 20-degree','knownSDS':'known SDS','mixtureSDS':'mixture SDS','liquidSDS':'liquid SDS','theS07':'the S07','theP02':'the P02','the1:4':'the 1:4','The80,000':'The 80,000','The2004':'The 2004','the2004':'the 2004','the1951':'the 1951','the1954':'the 1954','The1954':'The 1954','The1950':'The 1950','Original1950':'Original 1950','Original1954':'Original 1954','The2001':'The 2001','about40,000':'about 40,000','followed34,439':'followed 34,439','among649':'among 649','full1995':'full 1995','about1-in8':'about 1 in 8','GHSclassifications':'GHS classifications'}
    parts=re.split(r'(https?://[^\s)]+|`[^`]*`)',value)
    for i,part in enumerate(parts):
        if part.startswith(('http','`')):continue
        for old,new in terms.items():part=part.replace(old,new)
        part=re.sub(r'(?<=[A-Za-z])(19\d{2}|20\d{2})',r' \1',part)
        part=re.sub(r'((?:19|20)\d{2})(?=[A-Za-z])',r'\1 ',part)
        part=re.sub(r'(?<=\d)(mg/L|degrees|years|men\b|women\b|times\b|pairs\b|fish\b|cases\b|controls\b|students\b)',r' \1',part)
        part=re.sub(r'(?<=[a-z])(?=[A-Z][a-z])',' ',part)
        prefixes='about|from|to|and|in|at|for|per|below|above|aged|age|of|with|after|before|since|first|last|both|only|almost|over|near|depletion|residual|drop|rate|rates|counts|count|deaths|incidence|prevalence|mortality|Table|finding|column'
        suffixes='and|to|in|for|at|with|from|per|of|versus|is|are|as|has|have|means|while|about|mol|mg|mL|degrees|days|years|count|rate|cases|deaths|men|women|people|population|standard|projected|rise|rises|falls|times|halves|million|km|series'
        part=re.sub(r'\b('+prefixes+r')(?=\d)',r'\1 ',part,flags=re.I)
        part=re.sub(r'(?<=\d)('+suffixes+r')(?=\d|\b)',r' \1',part)
        part=re.sub(r'\b('+prefixes+r')(?=\d)',r'\1 ',part,flags=re.I)
        part=re.sub(r'(?<=%)(?=[A-Za-z])',' ',part)
        part=re.sub(r'(?<=[A-Za-z%])([.!?])(?=\d)',r'\1 ',part)
        part=re.sub(r'\b(with|for|and|an|the|after|before|same|no|from|exact)(?=AIHW|NESA|BOD|DNA|SDS|B11|Q[123])',r'\1 ',part)
        part=re.sub(r'(AIHW|NESA|BOD|DNA|SDS)(?=[a-z])',r'\1 ',part)
        part=part.replace('AIart','AI art').replace('x100000','x 100000').replace('x1000','x 1000').replace('x32.00','x 32.00')
        parts[i]=part
    return ''.join(parts)
